"""Build Phase 2 free-tool routes and an explicitly coming-soon app overview."""
from pathlib import Path
import re,html
from build_pages import header,footer
ROOT=Path(__file__).resolve().parent.parent
PUB=ROOT/'public'
TOOLS=[
 ('one-rep-max','1RM calculator','Estimate your strongest single rep.','Epley formula','↗','01'),
 ('plates','Plate calculator','The right plates. Both sides.','Balanced loading','▥','02'),
 ('protein','Protein calculator','A practical starting point for protein.','Daily intake estimate','◈','03'),
 ('tdee','TDEE calculator','Understand your daily energy needs.','Mifflin–St Jeor','ϟ','04'),
 ('macros','Macro calculator','Turn your calories into a simple split.','Protein · carbs · fat','<svg viewBox="0 0 24 24" width="23" height="23" fill="none" aria-hidden="true"><path d="M10 3a9 9 0 1 0 11 11H10V3Z" stroke="currentColor" stroke-width="1.6" stroke-linejoin="round"/><path d="M14 2v8h8a9 9 0 0 0-8-8Z" fill="currentColor" fill-opacity=".55" stroke="currentColor" stroke-width="1.3"/></svg>','05'),
 ('body-fat','Body fat calculator','A tape-measure estimate, not a verdict.','Navy circumference method','◎','06')
]

def field(name,label,value,minval,maxval,measure='',hint='',step='any',full=False):
 unit={'mass':'kg','length':'cm','':' '}.get(measure,'')
 return f'''<div class="tool-field{' field-wide' if full else ''}"><label for="{name}">{label}</label><div class="tool-input"><input id="{name}" name="{name}" type="number" inputmode="decimal" value="{value}" min="{minval}" max="{maxval}" data-min="{minval}" data-max="{maxval}" step="{step}" {'data-measure='+measure if measure else ''} required><span data-unit-label="{measure}">{unit}</span></div>{f'<small>{hint}</small>' if hint else ''}</div>'''
def select(name,label,options,selected,full=False):
 return f'<div class="tool-field{" field-wide" if full else ""}"><label for="{name}">{label}</label><select id="{name}" name="{name}">'+''.join(f'<option value="{v}"'+(' selected' if str(v)==str(selected) else '')+f'>{l}</option>' for v,l in options)+'</select></div>'
sex=[('male','Male reference'),('female','Female reference')]
factors=[(1.4,'1.4 g/kg'),(1.6,'1.6 g/kg'),(1.8,'1.8 g/kg'),(2,'2.0 g/kg')]
activity=[('sedentary','Mostly seated · 1.20'),('light','Light activity · 1.375'),('moderate','Moderate activity · 1.55'),('very','Very active · 1.725'),('extra','Extremely active · 1.90')]
forms={
 'one-rep-max':field('weight','Weight lifted',80,1,1000,'mass','Use a recent working set, not an unsafe max attempt.')+field('reps','Repetitions',5,1,30,'','Whole reps. Estimates become less reliable above 10.',step='1'),
 'plates':field('target','Target total load',100,0,600,'mass','Includes the bar and both sides.')+field('bar','Bar weight',20,0,50,'mass','Check the weight printed on your bar.')+field('collars','Collars: combined weight',0,0,10,'mass','Both collars together. Leave 0 if excluded.',full=True)+'<fieldset class="plate-inventory field-wide"><legend>Available plate pairs</legend><p>One pair = one matching plate for each side. Enter 0 for plates you do not have.</p><div id="plate-inventory"></div></fieldset>',
 'protein':field('weight','Bodyweight',80,30,300,'mass')+select('multiplier','Protein factor',factors,1.6)+field('meals','Meals / portions',4,1,8,'','Used only to divide the daily total evenly.',step='1',full=True),
 'tdee':field('weight','Bodyweight',80,30,300,'mass')+field('height','Height',180,120,230,'length')+field('age','Age',30,18,100,'','Adults only.',step='1')+select('sex','Formula reference',sex,'male')+select('activity','Overall activity',activity,'moderate',True),
 'macros':field('weight','Bodyweight',80,30,300,'mass')+field('calories','Daily energy (kcal)',2400,1200,8000,'','Enter your own energy estimate. This tool does not set a calorie deficit.')+select('proteinMultiplier','Protein factor',factors,1.6)+select('fatPercent','Calories from fat',[(20,'20%'),(25,'25%'),(30,'30%'),(35,'35%')],25),
 'body-fat':select('sex','Formula reference',sex,'male',True)+field('height','Height',180,120,230,'length')+field('neck','Neck circumference',39,20,70,'length','Measure below the larynx; keep shoulders relaxed.')+field('waist','Abdomen at navel',88,45,200,'length','Tape level, snug, not compressing the skin.')+'<div id="hip-field">'+field('hip','Hip circumference',100,50,220,'length','Female formula only: around the widest part of the hips.')+'</div>'
}
methods={
 'one-rep-max':('The Epley estimate','<code>Estimated 1RM = load × (1 + repetitions / 30)</code><p>For a single repetition, this tool uses the entered load directly instead of adding the formula’s extra 3.3%. It accepts 1–30 whole repetitions. More reps and sets far from failure can make the estimate less reliable.</p><p>The percentage table is arithmetic, not a workout prescription. No estimate guarantees you can safely lift the displayed weight. A calculated 1RM is separate from Monte Wo’s <a href="/strength/">MONTE WO Strength Index™</a>.</p>'),
 'plates':('How the plate planner works','<code>Plate weight per side = (target − bar − both collars) / 2</code><p>The planner searches the selected inventory for the closest balanced load at or below your target, then uses the fewest plates for that load. It never uses more pairs than you entered. If several combinations tie, larger plates are considered first.</p><p>There is no mixed kg/lb loading. Switching units resets the target, bar, collars, and inventory to common defaults for that unit. Sleeve space, bar rating, plate diameter, and equipment condition are not checked. Verify your actual hardware and load both sides equally.</p>'),
 'protein':('An estimate for active adults','<code>Daily protein (g) = bodyweight (kg) × selected g/kg factor</code><p>The ISSN position stand describes 1.4–2.0 g/kg/day as sufficient for most exercising individuals. <a href="https://link.springer.com/article/10.1186/s12970-017-0177-8" target="_blank" rel="noopener noreferrer">[2]</a> This tool lets you explore that range; the default 1.6 g/kg is a planning choice, not a personalized prescription.</p><p>Per-meal figures simply divide the daily total by your selected number of portions. They do not prescribe meal timing or require supplements. This is not a clinical calculator for kidney disease or other conditions requiring individualized intake advice.</p>'),
 'tdee':('Resting energy × activity','<code>Male REE = 10 × kg + 6.25 × cm − 5 × age + 5<br>Female REE = 10 × kg + 6.25 × cm − 5 × age − 161<br>TDEE = estimated REE × selected activity factor</code><p>These are the simplified Mifflin–St Jeor equations for resting energy expenditure (REE), often loosely called BMR in calculators. <a href="https://mifflinstjeor.com/mifflin-st-jeor-equation/" target="_blank" rel="noopener noreferrer">[1]</a> <a href="https://pubmed.ncbi.nlm.nih.gov/2305711/" target="_blank" rel="noopener noreferrer">Read the original paper ↗</a></p><p>The activity multipliers in this tool (1.20–1.90) are rough planning assumptions, not measured expenditure or part of the original REE equation. Your actual needs can differ. Reference sex chooses the equation coefficient; it is not a judgment of gender identity.</p><p>Supported inputs: adults 18–100, 30–300 kg, and 120–230 cm. These are software limits, not a guarantee the model fits every person in that range.</p>'),
 'macros':('A transparent calorie split','<code>Protein (g) = kg × selected factor<br>Fat (g) = calories × selected fat share ÷ 9<br>Carbohydrate (g) = [calories − 4 × protein(g) − 9 × fat(g)] ÷ 4</code><p>The calculator uses conventional calorie equivalents of 4 kcal/g for protein and carbohydrate, and 9 kcal/g for fat. The 1.4–2.0 g/kg protein range is informed by the ISSN position stand for exercising individuals. <a href="https://link.springer.com/article/10.1186/s12970-017-0177-8" target="_blank" rel="noopener noreferrer">[2]</a></p><p>The default 25% fat share is an editable planning assumption, not an individually optimized split. Carbohydrates receive the remaining calories. Display rounding can create small differences when adding grams back into calories.</p><p>This tool accepts 1,200–8,000 kcal as a software input range—not a declaration that those intakes are appropriate or safe for you. It does not recommend a calorie deficit. If protein and fat consume all available calories, no split is shown.</p>'),
 'body-fat':('A circumference-based estimate','<code>Male % = 86.010 × log10(abdomen − neck) − 70.041 × log10(height) + 36.76<br>Female % = 163.205 × log10(waist + hips − neck) − 97.684 × log10(height) − 78.387</code><p>These Navy-style equations use <strong>inches</strong>; metric entries are converted before calculation. <a href="https://calcilo.com/us/body-fat-calculator/" target="_blank" rel="noopener noreferrer">[2]</a> Measurements are self-reported and results are approximate, not a clinical body-composition measurement.</p><ul><li>Stand relaxed. Do not suck in your abdomen or compress the skin.</li><li>For the male formula, measure the abdomen at the navel.</li><li>For the female formula, measure the waist at its narrowest point and the hips at their widest.</li><li>Measure the neck below the larynx with your head neutral. Repeat measurements consistently.</li></ul><p>Measurement locations and equations are described in this <a href="https://rippedbody.com/how-calculate-body-fat-percentage/" target="_blank" rel="noopener noreferrer">[3]</a> method guide. The tool does not show results at or below 0% or at or above 70%, or invalid logarithm inputs; it does not clamp them to a reassuring number. This is a display guardrail, not a clinical classification. The formula may not fit your body.</p>')
}

def doc(title,body,tool=''):
 scripts='<script src="/site.js" type="module"></script>' + ('<script src="/tools.js" type="module"></script>' if tool else '')
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#090c13"><title>{html.escape(title)} | Monte Wo</title><meta name="description" content="{html.escape(title)} — free, private, offline-ready training tools from Monte Wo by VitaFlex."><link rel="icon" type="image/png" href="/assets/icon-32.png"><link rel="manifest" href="/manifest.json"><link rel="stylesheet" href="/fonts.css"><link rel="stylesheet" href="/style.css"><link rel="stylesheet" href="/launch.css"><link rel="stylesheet" href="/tools.css">{scripts}</head><body class="tools-page" {f'data-tool="{tool}"' if tool else ''}>{header}<main id="main">{body}</main>{footer}</body></html>'''
def save(route,text):
 directory=PUB/route;directory.mkdir(parents=True,exist_ok=True);(directory/'index.html').write_text(text)

def cards():
 return ''.join(f'''<a class="tool-card" href="/tools/{slug}/"><div class="tool-card-top"><span class="tool-symbol">{icon}</span><span class="tool-number">{num} / FREE TOOL</span></div><h2>{title}</h2><p>{description}</p><div class="tool-card-bottom"><span>{tag}</span><span aria-hidden="true">↗</span></div></a>''' for slug,title,description,tag,icon,num in TOOLS)
hub='''<section class="wrap tools-hero"><div><span class="eyebrow-pill"><span class="pulse"></span>THE MONTE WO TOOLKIT</span><h1>Train with purpose.<br><span>Know your numbers.</span></h1><p>Six free tools for the work you put in. Plan your lifts, understand your fuel, and make your next session a little simpler.</p><div class="tool-trust"><span>✓ No account</span><span>✓ On-device calculations</span><span>✓ Offline after first visit</span></div></div><div class="tool-hero-art" aria-hidden="true"><div class="toolkit-orbit"></div><div class="toolkit-card card-lift"><span>STRENGTH ESTIMATE</span><strong>93.3 <small>kg</small></strong><div class="mini-load-bar"><i></i><i></i><b></b><i></i><i></i></div><small>80 kg × 5 reps · Epley</small></div><div class="toolkit-card card-fuel"><div class="mini-macro-ring"></div><div><span>DAILY PROTEIN</span><strong>128 <small>g</small></strong><small>80 kg × 1.6 g/kg</small></div></div><span class="art-caption">ILLUSTRATIVE EXAMPLES · NOT A PERSONAL PLAN</span></div></section><section class="wrap tools-library"><div class="tool-section-heading"><div><span class="eyebrow">A STRONGER START</span><h2>Good tools. No barriers.</h2></div><span class="tool-count">06 TOOLS / ALWAYS WITH YOU</span></div><div class="tool-card-grid">'''+cards()+'''</div><div class="tools-privacy-note"><span>⌁</span><p>Inputs stay in this tab. These tools do not upload or save your measurements. Their static files can be cached for offline use. <a href="/privacy/">Your privacy ↗</a></p></div></section><section class="wrap tools-bottom"><div class="tool-guidance"><span class="eyebrow">A NUMBER IS A STARTING POINT.</span><h2>Useful estimates.<br>Not instructions for your body.</h2><p>Nutrition and body-composition tools are for general adult education, not medical or dietetic advice. They are not designed for children, pregnancy, breastfeeding, or clinical nutrition needs. If tracking numbers is distressing, it’s okay to skip these tools and seek support from a qualified professional.</p></div><div class="app-teaser"><span class="coming-label">THE CORE APP · COMING SOON</span><h2>Your training.<br>Your next level.</h2><p>Workout logs, ranked sets, streaks, and leaderboards—all part of the Monte Wo app we’re building.</p><a class="text-link" href="/app/">Explore what’s coming ↗</a></div></section>'''
lab_entry = '<section class="wrap"><div class="lab-entry"><p><strong>New: MONTE WO Strength Lab.</strong><br>Five focused lifting calculators. Free, local and independent of rankings.</p><a href="/strength-lab/">Open the Strength Lab ↗</a></div></section>'
hub = hub.replace('<section class="wrap tools-library">',lab_entry+'<section class="wrap tools-library">')
save('tools',doc('Free Fitness Tools',hub).replace('</head>','<link rel="stylesheet" href="/lab.css"></head>'))
for slug,title,description,tag,icon,num in TOOLS:
 unit_labels=('kg','lb') if slug in ['one-rep-max','plates','protein','macros'] else ('Metric','Imperial')
 nav='<nav class="tool-sidebar" aria-label="Free calculators"><a class="all-tools" href="/tools/">← All free tools</a>'+''.join(f'<a href="/tools/{s}/"'+(' aria-current="page"' if s==slug else '')+f'><span>{ic}</span>{ti}</a>' for s,ti,de,ta,ic,nu in TOOLS)+'</nav>'
 note='<p class="tool-health-note"><span>ⓘ</span> For adults 18+. General estimates only—not a personal nutrition plan or medical advice. Not intended for pregnancy, breastfeeding, or clinical needs.</p>' if slug in ['protein','tdee','macros','body-fat'] else '<p class="tool-health-note"><span>ⓘ</span> Use manageable loads and suitable equipment. A calculated number is not a reason to attempt an unsafe lift.</p>'
 subtitle='A rough estimate, not a target or health label.' if slug=='body-fat' else 'Make the math simpler. Keep the work yours.'
 methodtitle,methodbody=methods[slug]
 body=f'''<section class="wrap tool-page-heading"><a class="back-home" href="/tools/">← The Monte Wo toolkit</a><span class="eyebrow">{num} / FREE TOOL / {tag.upper()}</span><h1>{title}</h1><p>{description} {subtitle}</p></section><div class="wrap calculator-workspace">{nav}<div class="tool-workspace-main"><div class="tool-calculation-grid"><section class="tool-form-card"><div class="tool-form-heading"><h2>Your inputs</h2><div class="tool-unit-toggle" role="group" aria-label="Measurement units"><button type="button" data-tool-unit="metric" class="active" aria-pressed="true">{unit_labels[0]}</button><button type="button" data-tool-unit="imperial" aria-pressed="false">{unit_labels[1]}</button></div></div><form id="free-tool-form"><div class="tool-fields">{forms[slug]}</div><div id="tool-error" class="tool-error" role="alert"></div><div class="tool-form-actions"><button class="button" type="submit">Calculate <span aria-hidden="true">↗</span></button><button id="tool-reset" class="reset-button" type="button">Reset</button></div></form><p class="tool-local-note">⌁ Calculated here. Not saved or sent.</p></section><section id="tool-result" class="tool-result-card" aria-live="polite" aria-label="Calculator result"><div class="result-empty">Loading the calculator…</div></section></div>{note}<details class="tool-method" open><summary>{methodtitle}<span>+</span></summary><div>{methodbody}</div></details><div class="tool-next"><div><span class="eyebrow">MORE THAN NUMBERS</span><p>The ranked tracker is coming. The tools are here now.</p></div><a href="/app/" class="text-link">Meet the future app ↗</a></div></div></div>'''
 save('tools/'+slug,doc(title,body,slug))
app='''<section class="wrap core-app-hero"><div class="prelaunch-pill">THE CORE APP · COMING SOON</div><h1>Log the work.<br><span>Watch yourself rise.</span></h1><p>Monte Wo is becoming a home for your training: the sets, the small wins, and the climb you share with others.</p><div class="core-hero-actions"><a class="button" href="/waitlist/">Join the waitlist ↗</a><a class="text-link" href="/tools/">Use the free tools now ↗</a></div><small>No native app download or launch date announced yet.</small></section><section class="wrap roadmap-section"><div class="roadmap-label"><span class="eyebrow">THE EXPERIENCE WE’RE BUILDING</span><span>PLANNED FEATURES · NOT AVAILABLE YET</span></div><div class="roadmap-grid"><article class="roadmap-card"><span class="roadmap-icon">＋</span><span class="roadmap-status">COMING SOON</span><h2>Log every working set.</h2><p>Record your exercise, weight, and repetitions. Keep your sessions organized and your training history close.</p><div class="roadmap-visual log-concept"><span>BENCH PRESS</span><div><b>SET 01</b><strong>80 <small>kg</small></strong><strong>5 <small>reps</small></strong></div><small>ILLUSTRATIVE CONCEPT ONLY</small></div></article><article class="roadmap-card"><span class="roadmap-icon">◇</span><span class="roadmap-status">COMING SOON</span><h2>A score. A rank. A next step.</h2><p>Only qualifying performances under approved discipline-specific standards can earn ranks. Workout logs and streaks never promote an athlete.</p><div class="roadmap-visual ranked-concept" data-rank-score="draft"><span>DRAFT — NOT OFFICIAL</span><div><span data-rank-logo class="concept-rank-logo"></span><b data-rank-name>DRAFT</b><strong><span data-rank-score-value>—</span> <small>/ —</small></strong></div><i><span data-rank-progress></span></i><small>Debitan → Bati → Solid → Fò → Avanse → Mèt → Chanpyon → Titan → Lejand</small></div></article><article class="roadmap-card"><span class="roadmap-icon">↗</span><span class="roadmap-status">COMING SOON</span><h2>Progress you can follow.</h2><p>Keep track of your lifting history, personal milestones, and the changes that are easy to miss between sessions.</p><div class="roadmap-visual progress-concept"><span>YOUR CLIMB, OVER TIME</span><svg viewBox="0 0 240 70" aria-hidden="true"><path d="M0 66H240M0 33H240" stroke="#283f58" stroke-dasharray="3 6"/><path d="M3 61 36 52 65 56 99 35 130 39 161 23 195 27 235 5" stroke="#5aadff" stroke-width="3" fill="none"/></svg><small>ILLUSTRATIVE CONCEPT ONLY</small></div></article><article class="roadmap-card"><span class="roadmap-icon">♨</span><span class="roadmap-status">COMING SOON</span><h2>Consistency, made visible.</h2><p>Build workout streaks and celebrate milestones. Gamified progress should support sustainable training—not pressure you to skip recovery.</p><div class="roadmap-visual streak-concept"><div><span>M</span><span>T</span><span>W</span><span>T</span><span>F</span><span>S</span><span>S</span></div><div><i>✓</i><i>✓</i><i>·</i><i>✓</i><i>·</i><i>·</i><i>·</i></div><small>CONCEPT · STREAK RULES STILL IN DESIGN</small></div></article><article class="roadmap-card roadmap-leaderboards"><span class="roadmap-icon">♛</span><span class="roadmap-status">COMING SOON</span><h2>A little friendly competition.</h2><p>Three ways to find your place in the climb. Leaderboards are planned; there are no live rankings or connected player profiles in this website.</p><div class="leaderboard-modes"><div><span>◉</span><h3>Friends</h3><p>Share the climb with your training circle.</p></div><div><span>◎</span><h3>Global</h3><p>See the wider Monte Wo community.</p></div><div><span>⌖</span><h3>Regional</h3><p>Find your local competitive community.</p></div></div><small>Visibility, regional eligibility, verification, and privacy controls are still to be defined. No location is collected for leaderboards today.</small></article></div><div class="roadmap-disclosure"><strong>An honest preview.</strong><p>These are planned features—not a working app dashboard. No official rank is awarded while the Strength Index methodology remains unapproved. Joining the waitlist creates no app account.</p><a href="/methodology/" class="text-link">Read the MONTE Standard ↗</a></div></section><section class="wrap"><div class="core-end"><h2>More workouts are coming.</h2><p>More exercises, workout routines and offline training guides are planned for the app. Until then, explore the written guides on our website.</p><a class="text-link" href="/exercises/">Explore the exercise library ↗</a><a class="button" href="/tools/">Explore the free tools ↗</a><a class="text-link" href="/waitlist/">Join the waitlist ↗</a></div></section>'''
save('app',doc('The Core App — Coming Soon',app))
print('Generated tool hub, six calculators, and coming-soon app page.')
